dashboard.definition:
{
  "title": "Homelab Operations",
  "description": "Proxmox nodes and guests, VM hosts, Docker and k3s, from index=metrics (OTel collectors and Proxmox's OpenTelemetry metric server, 60 s resolution).",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-4h@m,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {}
        }
      }
    }
  },
  "visualizations": {
    "viz_h_status": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Status",
        "fontSize": "large"
      }
    },
    "viz_hosts": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_hosts_reporting"
      },
      "title": "Hosts reporting (5 min)",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()"
      }
    },
    "viz_silent": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_hosts_silent_count"
      },
      "title": "Hosts silent > 5 min",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_cpuhot": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_cpu_hot"
      },
      "title": "Hosts CPU > 85%",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_fsfull": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_fs_full"
      },
      "title": "Filesystems > 85% full",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_vms": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_vms_running"
      },
      "title": "Proxmox guests running",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()"
      }
    },
    "viz_pods": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_pods_bad"
      },
      "title": "Pods not Running/Succeeded",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_restarts": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_restarts_24h"
      },
      "title": "Container restarts (24 h)",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_silent_tbl": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_hosts_silent"
      },
      "title": "Hosts that stopped sending metrics (last 24 h)",
      "options": {
        "count": 20
      }
    },
    "viz_h_pve": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Proxmox",
        "fontSize": "large"
      }
    },
    "viz_pve_nodes": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_pve_nodes"
      },
      "title": "Nodes",
      "options": {
        "count": 20
      }
    },
    "viz_pve_guests": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_pve_guests"
      },
      "title": "Guests (VMs and containers), last 10 min. Proxmox counts a VM's page cache as used memory; the Hosts section shows the guest's own view. PSI = % of time stalled on CPU / I/O / memory",
      "options": {
        "count": 20
      }
    },
    "viz_h_hosts": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Hosts: utilization and saturation",
        "fontSize": "large"
      }
    },
    "viz_cpu": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_cpu_busy"
      },
      "title": "CPU busy %",
      "options": {
        "yAxisTitleText": "%",
        "xAxisTitleVisibility": "hide",
        "legendDisplay": "right"
      }
    },
    "viz_mem": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_mem_used"
      },
      "title": "Memory used % (excludes cache)",
      "options": {
        "yAxisTitleText": "%",
        "xAxisTitleVisibility": "hide",
        "legendDisplay": "right"
      }
    },
    "viz_load": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_load_per_cpu"
      },
      "title": "Load (5 min) per CPU: above 1 means a run queue",
      "options": {
        "yAxisTitleText": "load / CPU",
        "xAxisTitleVisibility": "hide",
        "legendDisplay": "right"
      }
    },
    "viz_diskbusy": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_disk_busy"
      },
      "title": "Busiest disk, % of time busy",
      "options": {
        "yAxisTitleText": "%",
        "xAxisTitleVisibility": "hide",
        "legendDisplay": "right"
      }
    },
    "viz_net": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_net_mbps"
      },
      "title": "Network throughput (Mbit/s, in + out)",
      "options": {
        "yAxisTitleText": "Mbit/s",
        "xAxisTitleVisibility": "hide",
        "legendDisplay": "right"
      }
    },
    "viz_diskio": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_disk_mbs"
      },
      "title": "Disk throughput (MB/s, read + write)",
      "options": {
        "yAxisTitleText": "MB/s",
        "xAxisTitleVisibility": "hide",
        "legendDisplay": "right"
      }
    },
    "viz_fs": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_filesystems"
      },
      "title": "Filesystems",
      "options": {
        "count": 20
      }
    },
    "viz_storage": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_pve_storage"
      },
      "title": "Proxmox storage pools",
      "options": {
        "count": 20
      }
    },
    "viz_neterr": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_net_errors"
      },
      "title": "Network errors and drops (24 h)",
      "options": {
        "count": 20
      }
    },
    "viz_swap": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_swap"
      },
      "title": "Swap in use",
      "options": {
        "count": 20
      }
    },
    "viz_h_docker": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Docker containers",
        "fontSize": "large"
      }
    },
    "viz_containers": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_containers"
      },
      "title": "Containers (last 10 min)",
      "options": {
        "count": 20
      }
    },
    "viz_h_k8s": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Kubernetes (k3s-01)",
        "fontSize": "large"
      }
    },
    "viz_k8s_phase": {
      "type": "splunk.area",
      "dataSources": {
        "primary": "ds_k8s_phase"
      },
      "title": "Pods by phase",
      "options": {
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide"
      }
    },
    "viz_k8s_node": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_k8s_node"
      },
      "title": "Node usage (kubelet)",
      "options": {
        "yAxisTitleText": "",
        "xAxisTitleVisibility": "hide",
        "legendDisplay": "right"
      }
    },
    "viz_k8s_workloads": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_k8s_workloads"
      },
      "title": "Workloads: desired vs ready",
      "options": {
        "count": 20
      }
    },
    "viz_k8s_top": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_k8s_top_pods"
      },
      "title": "Top pods by memory",
      "options": {
        "count": 20
      }
    },
    "viz_k8s_restarts": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_k8s_restarts"
      },
      "title": "Containers that restarted (24 h)",
      "options": {
        "count": 20
      }
    },
    "viz_h_agents": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Agents (CronJobs on k3s-01, last 24 h)",
        "fontSize": "large"
      }
    },
    "viz_agents_health": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_agents_health"
      },
      "title": "Agent health: both agents run every 30 min; the Agents - not running or failing alert posts to Slack when this isn't ok",
      "options": {
        "count": 20
      }
    },
    "viz_ag_t_items": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_ag_t_items"
      },
      "title": "Ops agent: checks tripped",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()"
      }
    },
    "viz_ag_t_triaged": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_ag_t_triaged"
      },
      "title": "Ops agent: items triaged",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()"
      }
    },
    "viz_ag_t_attention": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_ag_t_attention"
      },
      "title": "Ops agent: not routine",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_ag_t_cost": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_ag_t_cost"
      },
      "title": "Ops agent: cost (USD, API-equivalent)",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()"
      }
    },
    "viz_ag_items": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_ag_items"
      },
      "title": "Ops agent: triaged items, not routine first",
      "options": {
        "count": 20
      }
    }
  },
  "dataSources": {
    "ds_hosts_reporting": {
      "type": "ds.search",
      "name": "hosts_reporting",
      "options": {
        "query": "| mstats count(system.uptime) as c where index=metrics earliest=-5m by host | stats count as hosts",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_hosts_silent": {
      "type": "ds.search",
      "name": "hosts_silent",
      "options": {
        "query": "| mstats count(system.uptime) as c where index=metrics earliest=-24h span=1m by host | stats max(_time) as last by host | eval age_min=round((now()-last)/60) | where age_min>5 | eval \"Last seen\"=strftime(last, \"%Y-%m-%d %H:%M\") | rename host as Host age_min as \"Minutes silent\" | table Host \"Last seen\" \"Minutes silent\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_hosts_silent_count": {
      "type": "ds.search",
      "name": "hosts_silent_count",
      "options": {
        "query": "| mstats count(system.uptime) as c where index=metrics earliest=-24h span=1m by host | stats max(_time) as last by host | eval age_min=round((now()-last)/60) | where age_min>5 | eval \"Last seen\"=strftime(last, \"%Y-%m-%d %H:%M\") | rename host as Host age_min as \"Minutes silent\" | table Host \"Last seen\" \"Minutes silent\" | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_cpu_hot": {
      "type": "ds.search",
      "name": "cpu_hot",
      "options": {
        "query": "| mstats avg(system.cpu.utilization) as idle where index=metrics state=idle earliest=-5m by host | where (1-idle)*100>85 | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_fs_full": {
      "type": "ds.search",
      "name": "fs_full",
      "options": {
        "query": "| mstats latest(system.filesystem.utilization) as u where index=metrics earliest=-10m by host mountpoint | where u>0.85 | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_vms_running": {
      "type": "ds.search",
      "name": "vms_running",
      "options": {
        "query": "| mstats latest(proxmox_vm_uptime) as up where index=metrics earliest=-5m by vmid | where up>0 | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_pods_bad": {
      "type": "ds.search",
      "name": "pods_bad",
      "options": {
        "query": "| mstats latest(k8s.pod.phase) as p where index=metrics earliest=-5m by k8s.namespace.name k8s.pod.name | where p!=2 AND p!=3 | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_restarts_24h": {
      "type": "ds.search",
      "name": "restarts_24h",
      "options": {
        "query": "| mstats max(k8s.container.restarts) as mx min(k8s.container.restarts) as mn where index=metrics earliest=-24h by k8s.pod.name k8s.container.name | eval r=mx-mn | stats sum(r) as k | appendcols [| mstats sum(container.restarts) as d where index=metrics earliest=-24h] | eval restarts=round(coalesce(k,0)+coalesce(d,0)) | fields restarts",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_pve_nodes": {
      "type": "ds.search",
      "name": "pve_nodes",
      "options": {
        "query": "| mstats latest(proxmox_node_cpustat_cpu) as cpu latest(proxmox_node_cpustat_cpus) as cpus latest(proxmox_node_memory_memused) as mu latest(proxmox_node_memory_memtotal) as mt latest(proxmox_node_cpustat_avg5) as load5 latest(proxmox_node_uptime) as up where index=metrics earliest=-10m by node | join type=left node [| mstats latest(proxmox_vm_uptime) as vup where index=metrics earliest=-10m by node vmid | eval running=if(vup>0,1,0) | stats sum(running) as running count as guests by node] | eval \"CPU %\"=round(cpu*100,1), \"Memory %\"=round(mu/mt*100,1), \"Memory GB\"=round(mu/1073741824,1).\" / \".round(mt/1073741824), \"Load (5m) per CPU\"=round(load5/cpus,2), \"Guests running\"=running.\" / \".guests, \"Uptime (days)\"=round(up/86400,1) | rename node as Node cpus as CPUs | table Node CPUs \"CPU %\" \"Load (5m) per CPU\" \"Memory %\" \"Memory GB\" \"Guests running\" \"Uptime (days)\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_pve_guests": {
      "type": "ds.search",
      "name": "pve_guests",
      "options": {
        "query": "| mstats latest(proxmox_vm_cpu) as cpu latest(proxmox_vm_cpus) as vcpu latest(proxmox_vm_mem) as mem latest(proxmox_vm_maxmem) as maxmem latest(proxmox_vm_uptime) as up avg(proxmox_vm_pressurecpusome) as cpu_psi avg(proxmox_vm_pressureiosome) as io_psi avg(proxmox_vm_pressurememorysome) as mem_psi sum(proxmox_vm_netin_total) as netin sum(proxmox_vm_netout_total) as netout sum(proxmox_vm_diskread_total) as dr sum(proxmox_vm_diskwrite_total) as dw where index=metrics earliest=-10m by name vmid node type | eval Status=if(up>0,\"running\",\"stopped\"), \"CPU %\"=round(cpu*100,1), \"Memory % (Proxmox view)\"=if(maxmem>0, round(mem/maxmem*100,1), null()), \"Memory GB\"=round(mem/1073741824,1).\" / \".round(maxmem/1073741824,1), \"Net in KB/s\"=round(netin/600/1024,1), \"Net out KB/s\"=round(netout/600/1024,1), \"Disk read MB/s\"=round(dr/600/1048576,2), \"Disk write MB/s\"=round(dw/600/1048576,2), \"PSI cpu/io/mem %\"=round(cpu_psi,1).\" / \".round(io_psi,1).\" / \".round(mem_psi,1), \"Uptime (days)\"=round(up/86400,1) | rename name as Guest vmid as VMID node as Node type as Type vcpu as vCPU | sort Status -\"CPU %\" | table Guest VMID Type Node Status vCPU \"CPU %\" \"Memory % (Proxmox view)\" \"Memory GB\" \"PSI cpu/io/mem %\" \"Net in KB/s\" \"Net out KB/s\" \"Disk read MB/s\" \"Disk write MB/s\" \"Uptime (days)\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_pve_storage": {
      "type": "ds.search",
      "name": "pve_storage",
      "options": {
        "query": "| mstats latest(proxmox_storage_used) as used latest(proxmox_storage_total) as total where index=metrics earliest=-10m by node storage | where total>0 | eval \"Used %\"=round(used/total*100,1), \"Used GB\"=round(used/1073741824), \"Total GB\"=round(total/1073741824) | rename node as Node storage as Storage | sort - \"Used %\" | table Node Storage \"Used %\" \"Used GB\" \"Total GB\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_cpu_busy": {
      "type": "ds.search",
      "name": "cpu_busy",
      "options": {
        "query": "| mstats avg(system.cpu.utilization) as idle where index=metrics state=idle span=5m by host | eval busy=round((1-idle)*100,1) | xyseries _time host busy",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_mem_used": {
      "type": "ds.search",
      "name": "mem_used",
      "options": {
        "query": "| mstats avg(system.memory.utilization) as u where index=metrics state=used span=5m by host | eval u=round(u*100,1) | xyseries _time host u",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_load_per_cpu": {
      "type": "ds.search",
      "name": "load_per_cpu",
      "options": {
        "query": "| mstats avg(system.cpu.load_average.5m) as l avg(system.cpu.logical.count) as n where index=metrics span=5m by host | eval l=round(l/n,2) | xyseries _time host l",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_disk_busy": {
      "type": "ds.search",
      "name": "disk_busy",
      "options": {
        "query": "| mstats sum(system.disk.io_time) as t where index=metrics span=5m by host device | eval busy=round(t/300*100,1) | stats max(busy) as busy by _time host | xyseries _time host busy",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_net_mbps": {
      "type": "ds.search",
      "name": "net_mbps",
      "options": {
        "query": "| mstats sum(system.network.io) as b where index=metrics span=5m by host | eval mbps=round(b*8/300/1000000,2) | xyseries _time host mbps",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_net_errors": {
      "type": "ds.search",
      "name": "net_errors",
      "options": {
        "query": "| mstats sum(system.network.errors) as e sum(system.network.dropped) as d where index=metrics earliest=-24h by host device | where e>0 OR d>0 | eval e=round(e), d=round(d) | rename host as Host device as Interface e as \"Errors (24h)\" d as \"Dropped (24h)\" | sort - \"Errors (24h)\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_disk_mbs": {
      "type": "ds.search",
      "name": "disk_mbs",
      "options": {
        "query": "| mstats sum(system.disk.io) as b where index=metrics span=5m by host | eval v=round(b/300/1048576,2) | xyseries _time host v",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_filesystems": {
      "type": "ds.search",
      "name": "filesystems",
      "options": {
        "query": "| mstats latest(system.filesystem.usage) as v where index=metrics earliest=-10m by host mountpoint state | eval {state}=v | stats sum(used) as used sum(free) as free by host mountpoint | eval \"Used %\"=round(used/(used+free)*100,1), \"Free GB\"=round(free/1073741824,1), \"Size GB\"=round((used+free)/1073741824) | rename host as Host mountpoint as Mount | sort - \"Used %\" | table Host Mount \"Used %\" \"Free GB\" \"Size GB\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_swap": {
      "type": "ds.search",
      "name": "swap",
      "options": {
        "query": "| mstats avg(system.paging.utilization) as u where index=metrics state=used earliest=-10m by host | eval \"Swap used %\"=round(u*100,1) | where 'Swap used %'>0 | rename host as Host | sort - \"Swap used %\" | table Host \"Swap used %\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_containers": {
      "type": "ds.search",
      "name": "containers",
      "options": {
        "query": "| mstats latest(container.cpu.utilization) as cpu latest(container.memory.usage.total) as mem latest(container.memory.percent) as mempct latest(container.uptime) as up where index=metrics earliest=-10m by host container.name container.image.name | eval \"CPU %\"=round(cpu,1), \"Memory MB\"=round(mem/1048576), \"Memory % of limit\"=round(mempct,1), \"Uptime (h)\"=round(up/3600,1) | rename host as Host container.name as Container container.image.name as Image | sort - \"CPU %\" | table Host Container Image \"CPU %\" \"Memory MB\" \"Memory % of limit\" \"Uptime (h)\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_k8s_phase": {
      "type": "ds.search",
      "name": "k8s_phase",
      "options": {
        "query": "| mstats latest(k8s.pod.phase) as p where index=metrics span=5m by k8s.pod.name | eval phase=case(p==1,\"Pending\",p==2,\"Running\",p==3,\"Succeeded\",p==4,\"Failed\",true(),\"Unknown\") | timechart span=5m count by phase",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_k8s_workloads": {
      "type": "ds.search",
      "name": "k8s_workloads",
      "options": {
        "query": "| mstats latest(k8s.deployment.desired) as want latest(k8s.deployment.available) as have where index=metrics earliest=-10m by k8s.namespace.name k8s.deployment.name | rename k8s.deployment.name as Workload | eval Kind=\"Deployment\" | append [| mstats latest(k8s.statefulset.desired_pods) as want latest(k8s.statefulset.ready_pods) as have where index=metrics earliest=-10m by k8s.namespace.name k8s.statefulset.name | rename k8s.statefulset.name as Workload | eval Kind=\"StatefulSet\"] | append [| mstats latest(k8s.daemonset.desired_scheduled_nodes) as want latest(k8s.daemonset.ready_nodes) as have where index=metrics earliest=-10m by k8s.namespace.name k8s.daemonset.name | rename k8s.daemonset.name as Workload | eval Kind=\"DaemonSet\"] | eval Status=if(have<want,\"DEGRADED\",\"ok\") | rename k8s.namespace.name as Namespace want as Desired have as Ready | sort - Status Namespace | table Status Namespace Kind Workload Desired Ready",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_k8s_top_pods": {
      "type": "ds.search",
      "name": "k8s_top_pods",
      "options": {
        "query": "| mstats latest(k8s.pod.cpu.usage) as cpu latest(k8s.pod.memory.working_set) as mem where index=metrics earliest=-10m by k8s.namespace.name k8s.pod.name | join type=left k8s.namespace.name k8s.pod.name [| mstats latest(k8s.container.memory_limit) as lim where index=metrics earliest=-10m by k8s.namespace.name k8s.pod.name k8s.container.name | stats sum(lim) as lim by k8s.namespace.name k8s.pod.name] | eval \"CPU (millicores)\"=round(cpu*1000), \"Memory MB\"=round(mem/1048576), \"% of memory limit\"=if(lim>0, round(mem/lim*100,1), null()) | rename k8s.namespace.name as Namespace k8s.pod.name as Pod | sort - \"Memory MB\" | head 25 | table Namespace Pod \"CPU (millicores)\" \"Memory MB\" \"% of memory limit\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_k8s_restarts": {
      "type": "ds.search",
      "name": "k8s_restarts",
      "options": {
        "query": "| mstats max(k8s.container.restarts) as mx min(k8s.container.restarts) as mn where index=metrics earliest=-24h by k8s.namespace.name k8s.pod.name k8s.container.name | eval \"Restarts (24h)\"=mx-mn | where 'Restarts (24h)'>0 | rename k8s.namespace.name as Namespace k8s.pod.name as Pod k8s.container.name as Container mx as \"Restarts (total)\" | sort - \"Restarts (24h)\" | table Namespace Pod Container \"Restarts (24h)\" \"Restarts (total)\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_k8s_node": {
      "type": "ds.search",
      "name": "k8s_node",
      "options": {
        "query": "| mstats avg(k8s.node.cpu.usage) as cpu avg(k8s.node.memory.working_set) as mem where index=metrics span=5m | eval \"CPU (cores)\"=round(cpu,2), \"Memory GB\"=round(mem/1073741824,2) | fields _time \"CPU (cores)\" \"Memory GB\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_agents_health": {
      "type": "ds.search",
      "name": "agents_health",
      "options": {
        "query": "| makeresults | eval agent=split(\"sec,ops\", \",\") | mvexpand agent | fields agent | join type=left agent [search index=ai_agents sourcetype=homelab:agent kind=run earliest=-24h | stats max(_time) as last_run count as runs_24h by agent] | join type=left agent [search index=ai_agents sourcetype=homelab:agent kind=run earliest=-65m | stats count as runs sum(eval(if(status=\"error\",1,0))) as failed_runs sum(triaged) as triaged sum(triage_errors) as triage_errors latest(error) as last_error by agent] | fillnull value=0 runs failed_runs triaged triage_errors runs_24h | eval minutes_since=if(isnull(last_run), null(), round((now()-last_run)/60)) | eval Status=case(isnull(last_run), \"NOT RUNNING (24 h)\", minutes_since>75, \"NOT RUNNING\", runs>0 AND failed_runs==runs, \"RUNS FAILING\", triage_errors>0 AND triaged==0, \"TRIAGE FAILING\", true(), \"ok\") | eval Agent=if(agent==\"sec\", \"Security agent\", \"Ops agent\"), \"Last run\"=strftime(last_run, \"%Y-%m-%d %H:%M\") | rename minutes_since as \"Minutes ago\" runs as \"Runs (1 h)\" failed_runs as \"Failed (1 h)\" runs_24h as \"Runs (24 h)\" last_error as \"Last error (1 h)\" | table Status Agent \"Last run\" \"Minutes ago\" \"Runs (1 h)\" \"Failed (1 h)\" \"Runs (24 h)\" \"Last error (1 h)\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_ag_t_items": {
      "type": "ds.search",
      "name": "ag_t_items",
      "options": {
        "query": "index=ai_agents sourcetype=homelab:agent agent=ops kind=run | stats sum(collected) as n | fillnull value=0 n",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_ag_t_triaged": {
      "type": "ds.search",
      "name": "ag_t_triaged",
      "options": {
        "query": "index=ai_agents sourcetype=homelab:agent agent=ops kind=run | stats sum(triaged) as n | fillnull value=0 n",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_ag_t_attention": {
      "type": "ds.search",
      "name": "ag_t_attention",
      "options": {
        "query": "index=ai_agents sourcetype=homelab:agent agent=ops kind=item | rename triage.verdict as verdict triage.confidence as confidence triage.headline as headline triage.summary as summary triage.severity as agent_severity | where isnotnull(verdict) AND NOT verdict IN (\"expected_activity\", \"benign\", \"transient\") | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_ag_t_cost": {
      "type": "ds.search",
      "name": "ag_t_cost",
      "options": {
        "query": "index=ai_agents sourcetype=homelab:agent agent=ops kind=run | stats sum(cost_usd) as c | eval c=round(coalesce(c, 0), 2)",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_ag_items": {
      "type": "ds.search",
      "name": "ag_items",
      "options": {
        "query": "index=ai_agents sourcetype=homelab:agent agent=ops kind=item | rename triage.verdict as verdict triage.confidence as confidence triage.headline as headline triage.summary as summary triage.severity as agent_severity | where isnotnull(verdict) | eval rank=if(verdict IN (\"expected_activity\", \"benign\", \"transient\"), 1, 0), What=coalesce(headline, summary) | sort rank - _time | eval When=strftime(_time, \"%Y-%m-%d %H:%M\") | rename title as Item target_host as Host verdict as Verdict confidence as Confidence agent_severity as \"Agent severity\" | table When Verdict Confidence \"Agent severity\" Item Host What",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    }
  },
